/*
  ImportOpsDB V1.12 - Countries + Maritime/Air Locations
  SQL Server 2019+

  Purpose:
  - Populate cfg.COUNTRY with the full ISO 3166-1 country set.
  - Populate cfg.PORT with real maritime and airport locations
    based on UN/LOCODE reference data.
  - Idempotent: can be executed more than once.

  Notes:
  - port_code stores the 5-character UN/LOCODE (e.g. PECLL).
  - cfg.PORT has one port_type per row. If a UN/LOCODE supports
    both port and airport functions, SEA is used as primary type.
  - Existing matching records are updated/reactivated.
*/

USE [ImportOpsDB];
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

BEGIN TRY
    BEGIN TRANSACTION;

    /* =========================================================
       1. ISO COUNTRIES
       ========================================================= */
    CREATE TABLE #COUNTRY_SRC(
        country_code CHAR(2) NOT NULL PRIMARY KEY,
        country_name NVARCHAR(120) NOT NULL,
        iso3_code CHAR(3) NOT NULL
    );


    UPDATE c
       SET c.country_name = s.country_name,
           c.iso3_code = s.iso3_code,
           c.is_active = 1
      FROM cfg.COUNTRY c
      JOIN #COUNTRY_SRC s ON s.country_code = c.country_code;

    SELECT s.country_code,s.country_name,s.iso3_code,1
      FROM #COUNTRY_SRC s
     WHERE NOT EXISTS (
         SELECT 1
           FROM cfg.COUNTRY c
          WHERE c.country_code = s.country_code
     );

    /* =========================================================
       2. UN/LOCODE - MARITIME PORTS + AIRPORTS
       ========================================================= */
    CREATE TABLE #PORT_SRC(
        country_code CHAR(2) NOT NULL,
        port_code NVARCHAR(20) NOT NULL,
        port_name NVARCHAR(160) NOT NULL,
        city_name NVARCHAR(120) NULL,
        port_type VARCHAR(20) NOT NULL,
        PRIMARY KEY(country_code,port_code)
    );



















































    UPDATE p
       SET p.port_name = s.port_name,
           p.city_name = s.city_name,
           p.port_type = s.port_type,
           p.is_active = 1
      FROM cfg.PORT p
      JOIN #PORT_SRC s
        ON s.country_code = p.country_code
       AND s.port_code = p.port_code;

        country_code,port_code,port_name,city_name,port_type,is_active
    )
    SELECT
        s.country_code,s.port_code,s.port_name,s.city_name,s.port_type,1
      FROM #PORT_SRC s
     WHERE NOT EXISTS (
         SELECT 1
           FROM cfg.PORT p
          WHERE p.country_code = s.country_code
            AND p.port_code = s.port_code
     );

    /* Index used by GET /api/catalogs/ports?countryCode=XX&portType=YY */
    IF NOT EXISTS (
        SELECT 1
          FROM sys.indexes
         WHERE object_id = OBJECT_ID(N'cfg.PORT')
           AND name = N'IX_PORT_COUNTRY_TYPE_NAME'
    )
    BEGIN
        CREATE INDEX IX_PORT_COUNTRY_TYPE_NAME
            ON cfg.PORT(country_code,port_type,port_name)
            INCLUDE(port_code,city_name,is_active);
    END;

    COMMIT TRANSACTION;

    SELECT
        (SELECT COUNT(*) FROM cfg.COUNTRY WHERE is_active=1) AS ActiveCountries,
        (SELECT COUNT(*) FROM cfg.PORT WHERE is_active=1) AS ActiveLocations,
        (SELECT COUNT(*) FROM cfg.PORT WHERE is_active=1 AND port_type='SEA') AS SeaPorts,
        (SELECT COUNT(*) FROM cfg.PORT WHERE is_active=1 AND port_type='AIR') AS Airports;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH;
GO

/* Verification examples */
SELECT country_code,country_name,iso3_code
FROM cfg.COUNTRY
WHERE is_active=1
ORDER BY country_name;

SELECT port_id,country_code,port_code,port_name,city_name,port_type
FROM cfg.PORT
WHERE country_code='PE' AND is_active=1
ORDER BY port_type,port_name;

SELECT port_id,country_code,port_code,port_name,city_name,port_type
FROM cfg.PORT
WHERE country_code='CN' AND is_active=1
ORDER BY port_type,port_name;